    ["holdDown"] = { "Лежать после сбивания", "Сбитая с ног Ева остаётся на земле, пока вы не сделаете уклонение или прыжок. Выкл: она встаёт сама через секунду, как в игре." },
    ["gore.lowArm.enabled"] = { "Потеря руки при низком HP", "Удар, оставляющий Еве меньше порога «Рука отпадает ниже» (по умолчанию 25%), отсекает руку («Какая рука»), и она сражается без неё. Рука растворяясь возвращается при отдыхе в лагере или в следующей жизни." },
    ["gore.lowArm.below"] = { "Рука отпадает ниже", "С «Потерей руки при низком HP»: доля HP, ниже которой должен опустить удар, чтобы рука отпала (25%: четверть). «Отрастает с HP» ждёт хотя бы на 1% больше этого." },
