    ["gore.lowArm.notice"] = { "Уведомление «Нельзя»", "С «Без неё — ни лечения, ни пистолета»: нажатие прицеливания или лечения без руки показывает игровое уведомление «Сейчас нельзя использовать.» со звуком." },
