    ["bosses.face"] = { "Посмертное лицо босса", "С «Боссами песочницы» и «Посмертным выражением»: посмертное выражение держится на лице босса." },
    ["bosses.spawn_pick"] = { "Призвать босса", "С «Боссами песочницы»: выбранный выше босс в 7 м перед Евой, лицом к ней. Сразу вступает в бой." },
    ["bosses.remove"] = { "Убрать призванных", "Все боссы и враги, призванные здесь, исчезают, и трупы тоже." },
